/**
 * modules/CoreModule/suntime.js —— 真太阳时内核 C04【单一真源】
 *
 * 算什么：平太阳时 → 真太阳时；
 *   ① 经度校正：本地经度相对时区基准经度（东八区=120°E）每差 1° = 4 分钟（东加西减）；
 *   ② 真太阳时差（均时差 equation of time）：地球轨道偏心 + 黄赤交角造成的日差（约 ±16 分钟）；
 *   ③ 夏令时校正：中国 1986–1991 年执行过夏令时（每年 4 月中~9 月中，时钟拨快 1 小时）；
 *   ④ 时区兜底：出国场景手选 UTC 偏移。
 * 算法来源：经度/时区为常识公式；均时差用低精度天文近似式（与节气 NOAA 式同源）；夏令时区间为公开史料。
 * 校验收：  modules/CoreModule/__tests__/suntime.test.js
 * 加载：UMD —— require() 得 { correct, CITIES, DST }; 浏览器挂全局 NT.core.suntime。
 */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else { root.NT = root.NT || {}; root.NT.core = root.NT.core || {}; root.NT.core.suntime = factory(); }
})(typeof self !== 'undefined' ? self : this, function () {

  // 时区基准经度（东八区 = 120°E）
  var BASE_LON = 120;

  // 中国 1986–1991 年夏令时执行区间（公开史料，每年略有差异；离线内置）
  // 格式：[起始公历, 结束公历)  —— 期间时钟比标准时快 1 小时，求真太阳时须先减 1 小时
  var DST = [
    { y: 1986, from: [5, 4], to: [9, 14] },
    { y: 1987, from: [4, 12], to: [9, 13] },
    { y: 1988, from: [4, 10], to: [9, 11] },
    { y: 1989, from: [4, 16], to: [9, 17] },
    { y: 1990, from: [4, 15], to: [9, 16] },
    { y: 1991, from: [4, 14], to: [9, 15] }
  ];

  // 中国主要城市经度（°E，市中心近似值）。圣经 1.4 要求 300+ 城；此处先内置省会+主要地级市，
  // 后续按需扩充（数据单一真源，扩充只改本表）。
  var CITIES = {
    北京: 116.4, 上海: 121.47, 广州: 113.26, 深圳: 114.06, 成都: 104.07, 重庆: 106.55,
    天津: 117.2, 武汉: 114.3, 西安: 108.94, 南京: 118.78, 杭州: 120.16, 长沙: 112.94,
    郑州: 113.62, 石家庄: 114.5, 太原: 112.55, 济南: 117.0, 青岛: 120.38, 合肥: 117.23,
    福州: 119.3, 厦门: 118.09, 南昌: 115.9, 沈阳: 123.43, 大连: 121.62, 长春: 125.32,
    哈尔滨: 126.53, 宁波: 121.55, 苏州: 120.6, 无锡: 120.31, 佛山: 113.12, 东莞: 113.75,
    珠海: 113.58, 惠州: 114.41, 中山: 113.39, 泉州: 118.6, 洛阳: 112.45, 兰州: 103.83,
    贵阳: 106.7, 昆明: 102.74, 海口: 110.35, 南宁: 108.37, 乌鲁木齐: 87.62, 西宁: 101.77,
    银川: 106.23, 拉萨: 91.18, 呼和浩特: 111.75, 包头: 106.79, 温州: 120.7, 台州: 121.42,
    嘉兴: 120.76, 绍兴: 120.58, 金华: 119.65, 舟山: 122.2, 衢州: 118.87, 湖州: 120.09,
    香港: 114.17, 澳门: 113.55, 台北: 121.52,
    三亚: 109.51, 桂林: 110.29, 柳州: 109.42, 遵义: 106.9, 大理: 100.23, 丽江: 100.23,
    烟台: 121.39, 潍坊: 119.16, 淄博: 118.05, 唐山: 118.18, 保定: 115.48, 邯郸: 114.49,
    徐州: 117.18, 常州: 119.95, 南通: 120.86, 扬州: 119.42, 盐城: 120.16, 泰州: 119.9,
    芜湖: 118.38, 蚌埠: 117.36, 安庆: 117.05, 九江: 115.99, 赣州: 114.94, 宜春: 114.42,
    株洲: 113.13, 湘潭: 112.94, 衡阳: 112.6, 岳阳: 113.09, 常德: 111.69, 宜昌: 111.29,
    襄阳: 112.14, 荆州: 112.24, 十堰: 110.79, 新乡: 113.9, 安阳: 114.39, 焦作: 113.24,
    开封: 114.31, 南阳: 112.53, 许昌: 113.85, 平顶山: 113.32, 咸阳: 108.71, 宝鸡: 107.24,
    渭南: 109.51, 汉中: 107.02, 榆林: 109.74, 天水: 105.72, 白银: 104.14, 嘉峪关: 98.29,
    银川北: 106.28, 石嘴山: 106.38, 吴忠: 106.2, 中卫: 105.19, 西峰: 107.64, 张掖: 100.46,
    酒泉: 98.51, 敦煌: 94.66, 格尔木: 94.9, 德令哈: 97.36, 玉树: 97.01, 西昌: 102.26,
    攀枝花: 101.72, 绵阳: 104.68, 德阳: 104.4, 南充: 106.11, 宜宾: 104.63, 泸州: 105.44,
    自贡: 104.78, 内江: 105.06, 乐山: 103.76, 眉山: 103.85, 广元: 105.84, 遂宁: 105.57,
    曲靖: 103.8, 玉溪: 102.55, 保山: 99.17, 昭通: 103.72, 普洱: 100.97, 临沧: 100.09,
    安顺: 105.93, 六盘水: 104.83, 凯里: 107.98, 都匀: 107.52, 铜仁: 109.19, 毕节: 105.29,
    北海: 109.12, 钦州: 108.65, 防城港: 108.35, 贵港: 109.6, 玉林: 110.18, 百色: 106.62,
    河池: 108.09, 梧州: 111.28, 贺州: 111.55, 来宾: 109.23, 崇左: 107.36
  };

  // 均时差（equation of time，分钟）——低精度近似式，输入为该年第几天 N
  function equationOfTime(N) {
    var b = 2 * Math.PI * (N - 81) / 364;
    return 9.87 * Math.sin(2 * b) - 7.53 * Math.cos(b) - 1.5 * Math.sin(b);
  }
  function dayOfYear(y, m, d) {
    var start = Date.UTC(y, 0, 1), cur = Date.UTC(y, m - 1, d);
    return Math.floor((cur - start) / 86400000) + 1;
  }

  /** 是否在夏令时区间内（返回 true 表示时钟比标准时快 1 小时） */
  function isDST(y, m, d) {
    for (var i = 0; i < DST.length; i++) {
      var s = DST[i];
      if (s.y !== y) continue;
      var md = m * 100 + d, f = s.from[0] * 100 + s.from[1], t = s.to[0] * 100 + s.to[1];
      return md >= f && md < t;
    }
    return false;
  }

  /**
   * 真太阳时校正。
   * @param {Object} o { y,m,d,h,i, lon 或 city, tzOffset(可选,小时,默认8), applyDST(默认true) }
   * @returns { 标准时, 夏令时校正, 经度校正(分), 均时差(分), 真太阳时, 说明 }
   */
  function correct(o) {
    o = o || {};
    var lon = (o.lon != null) ? o.lon : (o.city && CITIES[o.city] != null ? CITIES[o.city] : null);
    if (lon == null) return { ok: false, 说明: '缺少经度或城市（可用内置城市名或直接给 lon）' };
    var tz = (o.tzOffset != null) ? o.tzOffset : 8;          // 时区偏移（小时）
    var tzBaseLon = tz * 15;                                  // 该时区基准经度
    var h = o.h || 0, mi = o.i || 0;
    // ① 夏令时：标准时 = 钟表时 - 1 小时（若在期）
    var dst = (o.applyDST === false) ? false : isDST(o.y, o.m, o.d);
    var stdMin = h * 60 + mi - (dst ? 60 : 0);
    // ② 经度校正（分）：(经度 - 时区基准经度) × 4
    var lonFix = (lon - tzBaseLon) * 4;
    // ③ 均时差（分）
    var eot = equationOfTime(dayOfYear(o.y, o.m, o.d));
    var trueMin = stdMin + lonFix + eot;
    // 归一化到 0–1440
    trueMin = ((trueMin % 1440) + 1440) % 1440;
    var th = Math.floor(trueMin / 60), tm = Math.round(trueMin % 60);
    if (tm === 60) { tm = 0; th = (th + 1) % 24; }
    function p2(n) { return (n < 10 ? '0' : '') + n; }
    return {
      ok: true,
      经度: lon, 时区偏移: tz,
      夏令时: dst,
      经度校正分: Math.round(lonFix * 10) / 10,
      均时差分: Math.round(eot * 10) / 10,
      真太阳时: p2(th) + ':' + p2(tm),
      说明: '真太阳时 = 标准时' + (dst ? '（已减夏令时1h）' : '') + ' + 经度差' + (lonFix >= 0 ? '+' : '') + Math.round(lonFix) + '分 + 均时差' + (eot >= 0 ? '+' : '') + Math.round(eot) + '分'
    };
  }

  return { correct: correct, CITIES: CITIES, DST: DST, isDST: isDST, equationOfTime: equationOfTime, BASE_LON: BASE_LON };
});
